INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467055-pete301', 'stk-user9306', 'PETE 301', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاتة\n\nالسمستر 161\n\nالدكتور:- حسن الهاشم (طاح المعدل بسسبه 😭 😭 😭 😭 😭 😭 😭)\nتحذيرات :-\n\nهذا الكورس راح يتسبب في كثير من التعب والالم لبعذ الطلاب وهذا يرجع الى اسباب عديدة:-\n1> الحلول في هذا المنهج طويل جدا جدا جدا لذلك لا بد ولا غنى عن استخدام الاكسل والدكتور الجبيب ممنوع تستخدم الاكسل عندة في الاختبار يعني بتقعد ساعة كامل على شان تحل السؤال\n\n2> الجميل في هذ الكورس ان مافيه لف ولا دوران لكن طول الامتاح والحسابات اللي راح تطلعها كفيلة انها تخسف درجتك وهي البديلة عن التريكات .\n\nالمنهج :-\nالمادة الجملية هذي تتكلم في البداية عن الماتيريال بالنس من تطبيقاتها إنك تقدر توجد حجم الزيت الموجود في اريزرفوار( N )تقدر برضوا تجيب so و sw وCf وال Cw بعد الانتاج لانها تتغير + تقدر تجيب حجم الغاز الموجود في الريزرفوار حتى لو كان نوع الريزرفوار understurated تقدر وبعد الانتاج صار في gas cap تقدر تجيب حجمة (G) هذا اللي طلعت فيه صراحة من هالمادة\n\nالجزء الثاني water influx\n\nوهو ببساطة بعض الابار تكون محاطة ب aquafier ولها تاثير كبير على الانتاج طبعا بحيث ان اذا استمريت ي انتاج الزيت راح يجيك وقت وبدل مانتج زيت راح تنج موية واللي هو غير مرغوب فية لذلك لازم تشوف البير حقك وتدرسة كويس علشان تتفادى اي مشاكل في المستقبل طبعا من خلال waterinlux طبعا عندك اكثر من model , وكل عالم له مودل خاص فية لكن الفرق يكون بيسط بينهم تقدر تحسب من خلال المودلز كمية الماء اللي بتوصل عن البير حقك We\n\nالجزء الثالث fractional flow\nهذا الجزء يكون اسهل نوعا ما من اللي قبلة\n\nبحيث إذا جبت بعض الاشياء الحل راح يكون جيبك الاشياء اللي لازم تجيبها:-\n1}\nماقبل ال break through\nfwf و\"swfa swf fwf\n\nهذي كلها تقدر تلطعها من القراف اللي يكون ال (y -axis (fw الx-axis (sw\n\n2}\n\nبعد الbreak through\n\nتجيب\n\"fwe ,fwe swe swavg , وبنفس الطريقة\n\nوفي اشياء ماحتضرني الحين لاكن حاولت قظر الامكان اجيب الاشياء المهمة في ذا الكورس ةاشرحها لعل وعسى احد يفهم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pete-301-reservoir-engineering/120463/3", "user": "user9306", "ts": 1485465114000, "tid": 120463, "pn": 3}}', 1485465114000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
